tic.com/45174159/r/il/e9a5ae/7840718133/il_794xN.7840718133_ttbl.jpg", "destination_url": "https://www.etsy.com/listing/4448391965/white-cotton-curtains-natural-light", "title": "White Cotton Curtains, Natural Light Filtering Drapes For Bedroom & Living Room", "body": "White Cotton Curtains, Natural Light Filtering Drapes For Bedroom & Living Room Style: minimal, natural. Materials: cotton, linen. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "801218658646993070", "new_title": "White Curtains for Bedroom and Living Room", "new_body": "White Curtains for Bedroom and Living Room from WOGOL. Explore the original Etsy listing for sizes, available options and current availability.", "checked_at": "2026-10-13T02:32:32.991Z"}, {"queue_id": "0f7ac35a-fceb-401c-8669-6325eeccb1d6", "shop": "WOGOL", "listing_id": "4450630323", "source_url": "https://www.etsy.com/listing/4450630323/white-linen-blend-cafe-curtain-kitchen", "category": "Cafe Curtains", "image_url": "https://i.etsystatic.com/45174159/r/il/51ead4/7819435487/il_794xN.7819435487_mpxl.jpg", "destination_url": "https://www.etsy.com/listing/4450630323/white-linen-blend-cafe-curtain-kitchen", "title": "White Linen Blend Cafe Curtain, Kitchen Window Tier, Rod Pocket", "body": "White Linen Blend Cafe Curtain, Kitchen Window Tier, Rod Pocket Style: minimal, natural. Materials: linen. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "801218658646993070", "new_title": "White Cafe Curtain for a Kitchen Window", "new_body": "White Cafe Curtain for a Kitchen Window from WOGOL. Explore the original Etsy listing for sizes, available options and current availability.", "checked_at": "2026-10-13T02:32:34.615Z"}]'::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status in ('draft','ready') and cv.status in ('draft','ready') and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url=x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id and h.platform='pinterest')
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 15 then raise exception 'Expected 15 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status='ready',title=x.new_title,body=x.new_body from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft';
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;
commit;
